// MiTechShots site script (generated by build_site.py)
(function () {
  var btn = document.querySelector('.menu-btn');
  var nav = document.getElementById('site-nav');
  if (btn && nav) {
    btn.addEventListener('click', function () {
      var open = nav.classList.toggle('open');
      btn.setAttribute('aria-expanded', open ? 'true' : 'false');
    });
  }

  var input = document.getElementById('guide-search');
  var list = document.getElementById('search-results');
  if (!input || !list || !window.MT_GUIDES) return;
  var active = -1;

  function norm(s) { return s.toLowerCase(); }
  function render(q) {
    q = norm(q.trim());
    list.innerHTML = '';
    active = -1;
    if (!q) { list.hidden = true; input.setAttribute('aria-expanded', 'false'); return; }
    // every query word must match the start of a word in the guide (so "rag" finds RAG, not "storage")
    var words = q.split(/\s+/).map(function (w) {
      return new RegExp('(^|[^a-z0-9])' + w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
    });
    var hits = window.MT_GUIDES.filter(function (g) {
      var hay = norm(g.title + ' ' + g.desc + ' ' + g.topics.join(' ') + ' ' + g.track);
      return words.every(function (re) { return re.test(hay); });
    }).slice(0, 8);
    if (!hits.length) {
      list.innerHTML = '<li class="empty">No guides match "' + q.replace(/[<>&"]/g, '') + '"</li>';
    } else {
      hits.forEach(function (g) {
        var li = document.createElement('li');
        li.setAttribute('data-track', g.key);
        li.innerHTML = '<a href="' + g.url + '"><span class="dot"></span><span><strong></strong><small></small></span></a>';
        li.querySelector('strong').textContent = g.title;
        li.querySelector('small').textContent = g.track + ' \u00b7 ' + g.desc;
        list.appendChild(li);
      });
    }
    list.hidden = false;
    input.setAttribute('aria-expanded', 'true');
  }
  function move(d) {
    var links = list.querySelectorAll('a');
    if (!links.length) return;
    if (active >= 0) links[active].classList.remove('active');
    active = (active + d + links.length) % links.length;
    links[active].classList.add('active');
    links[active].scrollIntoView({ block: 'nearest' });
  }
  input.addEventListener('input', function () { render(input.value); });
  input.addEventListener('keydown', function (e) {
    if (e.key === 'ArrowDown') { e.preventDefault(); move(1); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); move(-1); }
    else if (e.key === 'Enter') {
      var links = list.querySelectorAll('a');
      if (links.length) { e.preventDefault(); (links[active >= 0 ? active : 0]).click(); }
    } else if (e.key === 'Escape') { input.value = ''; render(''); }
  });
  document.addEventListener('click', function (e) {
    if (!e.target.closest('.search')) { list.hidden = true; input.setAttribute('aria-expanded', 'false'); }
  });
  document.addEventListener('keydown', function (e) {
    if (e.key === '/' && document.activeElement !== input && !/input|textarea/i.test(document.activeElement.tagName)) {
      e.preventDefault(); input.focus();
    }
  });
})();
